import { Component, input, output } from '@angular/core';
import { PIcon, Spinner } from '@primeicons/angular';
import { ButtonModule } from 'primeng/button';
import { EnumMapPipe } from '../../../pipes/enum-map';

export type ButtonColour = 'primary' | 'secondary';

export type ButtonSize = 'small' | 'normal' | 'large';

export type ButtonType = 'button' | 'submit' | 'reset';

@Component({
  selector: 'tikal-button',
  imports: [ButtonModule, PIcon, EnumMapPipe, Spinner],
  templateUrl: './button.html',
  styleUrl: './button.scss',
})
export class ButtonComponent {
  /** What icon should the button display? */
  readonly icon = input<string>('');

  /** What colour should the button be? */
  readonly colour = input<ButtonColour>('primary');

  /** What size should the button be? */
  readonly size = input<ButtonSize>('normal');

  /** @ignore */
  readonly sizeMap = {
    normal: undefined,
  };

  /** What text should the button display? */
  readonly label = input<string>();

  /** Is the action related to the button currently running? */
  readonly isLoading = input<boolean>(false);

  /** Should the button have an outline? */
  readonly outline = input<boolean>(false);

  /** What type should the button be? */
  readonly type = input<ButtonType>('button');

  /** Should the button only appear as text? */
  readonly text = input<boolean>(false);

  /** @ignore */
  readonly clicked = output<void>();

  /** What form should the button belong to? */
  readonly form = input<string>();
}

import { Component, input, signal } from '@angular/core';
import { disabled, form, required, FormRoot, FormField, maxLength } from '@angular/forms/signals';
import { InputComponent } from '../input/input';
import { ButtonComponent } from '../button/button';

type ChatFormData = {
  message: string;
};

@Component({
  selector: 'tikal-chat-form',
  imports: [FormRoot, FormField, InputComponent, ButtonComponent],
  templateUrl: './chat-form.html',
  styleUrl: './chat-form.scss',
})
export class ChatFormComponent {
  /** @ignore */
  private readonly chatFormData = signal<ChatFormData>({ message: '' });

  /** What should happen when the form is submitted? */
  readonly onSubmission = input.required<(message: string) => Promise<void>>();

  /** What placeholder should be displayed on the input? */
  readonly placeholder = input<string>();

  /** What is the max input length? */
  readonly maxLength = input<number>(50);

  /** What is the label of the input element? */
  readonly label = input<string>();

  /** @ignore */
  readonly chatForm = form(
    this.chatFormData,
    (schemaPath) => {
      required(schemaPath.message);
      maxLength(schemaPath.message, () => this.maxLength());
      disabled(schemaPath, { when: () => this.chatForm().submitting() });
    },
    {
      submission: {
        action: async (field) => {
          const message = field().value().message;

          await this.onSubmission()(message);

          field.message().reset('');
        },
      },
    },
  );
}

